'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['chooseAsset']);
const { chooseAsset } = api;

assert.strictEqual(chooseAsset(' primary.png ', ['first.png', 'second.png']), 'primary.png');
assert.strictEqual(chooseAsset('   ', [' ', ' first.png ', 'second.png']), 'first.png');
assert.strictEqual(chooseAsset('', ['', '   ']), null);
assert.strictEqual(chooseAsset('same', ['same', 'other']), 'same');
assert.strictEqual(chooseAsset('  x  ', []), 'x');
assert.strictEqual(chooseAsset(' ', []), null);

const alternatives = ['  a  ', '', 'b'];
const snapshot = alternatives.slice();
assert.strictEqual(chooseAsset('', alternatives), 'a');
assert.deepStrictEqual(alternatives, snapshot);

for (const primary of [null, undefined, 1, {}, []]) {
  assert.throws(() => chooseAsset(primary, []), TypeError);
}
for (const alternativesValue of [null, undefined, 'x', {}, 1]) {
  assert.throws(() => chooseAsset('x', alternativesValue), TypeError);
}
for (const bad of [[null], ['ok', 1], [{}], [undefined]]) {
  assert.throws(() => chooseAsset('primary', bad), TypeError);
}

